function validate([n, limit]) {
  if (!Number.isInteger(n) || n < 1 || n > 50) return 'n is a whole number from 1 to 50.';
  if (!Number.isInteger(limit) || limit < 1 || limit > 50) return 'limit is a whole number from 1 to 50.';
  return null;
}

