function distributeCandies(n, limit) {
  // Try every amount for all three children and count the triples that use exactly n candies.
  let count = 0;
  for (let a = 0; a <= limit; a++)
    for (let b = 0; b <= limit; b++)
      for (let c = 0; c <= limit; c++)
        if (a + b + c === n) count++;
  return count;
}

